mapper.select:
SELECT , COALESCE(m.match_count, 0) AS match_count, COALESCE(a.match_success_amount, 0) AS match_success_amount, COALESCE(a.match_fail_amount, 0) AS match_fail_amount, CASE WHEN COALESCE(a.reconciliation_total_count, 0) <= 0 OR (COALESCE(a.reconciliation_confirmed_count, 0) <= 0 AND COALESCE(a.reconciliation_partial_count, 0) <= 0) THEN 'toBeConfirm' WHEN COALESCE(a.reconciliation_confirmed_count, 0) >= COALESCE(a.reconciliation_total_count, 0) THEN 'confirmed' ELSE 'partialConfirm' END AS reconciliation_status FROM logistics_recon LEFT JOIN ( SELECT main_id, COUNT(*) FILTER (WHERE match_status = 'matched') AS match_count FROM logistics_recon_detail_sub WHERE is_deleted = false GROUP BY main_id ) m ON m.main_id = logistics_recon.id LEFT JOIN ( SELECT sub.main_id, SUM(sub.actual_amount) FILTER (WHERE sub.match_status = 'matched') AS match_success_amount, SUM(sub.actual_amount) FILTER (WHERE sub.match_status = 'failed') AS match_fail_amount, COUNT(*) AS reconciliation_total_count, COUNT(*) FILTER (WHERE sub.reconciliation_status = 'confirmed') AS reconciliation_confirmed_count, COUNT(*) FILTER (WHERE sub.reconciliation_status = 'partialConfirm') AS reconciliation_partial_count FROM logistics_recon_detail_sub sub WHERE sub.is_deleted = false GROUP BY sub.main_id ) a ON a.main_id = logistics_recon.id WHERE ${params.sqlMap.default} AND is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
create_time DESC

SELECT check_status AS tabFlag, count(*) AS count FROM logistics_recon WHERE is_deleted = FALSE
${params.permissionSql}
GROUP BY check_status
